    /// <summary>
    /// Customize this method to use Transdate for calculating paymentdate
    /// </summary>
    /// <returns>payment due date</returns>
    protected TransDate calcPaymDueDate()
    {
        TransDate               metBaseDate;
        TransDate               metSumDate;
        CustVendTransOpen       metCustVendTransOpenCalc   = custVendTransOpen.data();
        CustVendTransOpenData   metCustVendTransOpenData   = CustVendTransOpenData::construct(metCustVendTransOpenCalc);
        TransDate               metSystemMinimumDate       = dateNull();

        metBaseDate = metCustVendTransOpenCalc.TransDate;

        if (this.validateBaseDate(metBaseDate))
        {
            metSumDate = metCustVendTransOpenData.sumPaymDate(metBaseDate,
                                                        paymWeekDayFixed,
                                                        paymDateFixed,
                                                        minimumPaymDate,
                                                        metSystemMinimumDate);
        }

        return metSumDate;
    }

    /// <summary>
    /// Initiating  <c>METAMEXCustVendPaymProposalCalcPaym</c> class.
    /// </summary>
    /// <param name = "_ledgerJournalType">Customer payment type.</param>
    /// <returns><c>METAMEXCustVendPaymProposalCalcPaym</c> class</returns>
    public static METAMEXCustVendPaymProposalCalcPaym construct(LedgerJournalType  _ledgerJournalType)
    {
        METAMEXCustVendPaymProposalCalcPaym    metCustVendPaymProposalCalcPaym;

        metCustVendPaymProposalCalcPaym = new METAMEXCustVendPaymProposalCalcPaym();
        metCustVendPaymProposalCalcPaym.parmLedgerJournalType(_ledgerJournalType);

        return metCustVendPaymProposalCalcPaym;
    }
